45: function read (req, res, next, parse, debug, options) {
46:   if (onFinished.isFinished(req)) {
47:     debug('body already parsed')
48:     next()
49:     return
50:   }
51: 
52:   if (!('body' in req)) {
53:     req.body = undefined
54:   }
55: 
56:   // skip requests without bodies
57:   if (!hasBody(req)) {
58:     debug('skip empty body')
59:     next()
60:     return
61:   }
62: 
63:   debug('content-type %j', req.headers['content-type'])
64: 
65:   // determine if request should be parsed
66:   if (!options.shouldParse(req)) {
67:     debug('skip parsing')
68:     next()
69:     return
70:   }
71: 
72:   let encoding = null
73:   if (options?.skipCharset !== true) {
74:     encoding = getCharset(req) || options.defaultCharset
75: 
76:     // validate charset
77:     if (!!options?.isValidCharset && !options.isValidCharset(encoding)) {
78:       debug('invalid charset')
79:       next(createError(415, 'unsupported charset "' + encoding.toUpperCase() + '"', {
80:         charset: encoding,
81:         type: 'charset.unsupported'
82:       }))
83:       return
84:     }
85:   }
86: 
87:   let length
88:   let stream
89: 
90:   const verify = options.verify
91: 
92:   try {
93:     const contentEncoding = (req.headers['content-encoding'] || 'identity').toLowerCase()
94: 
95:     debug('content-encoding "%s"', contentEncoding)
96: 
97:     if (options.inflate === false && contentEncoding !== 'identity') {
98:       throw createError(415, 'content encoding unsupported', {
99:         encoding: contentEncoding,
100:         type: 'encoding.unsupported'
101:       })
102:     }
103: 
104:     // get the content stream
105:     if (contentEncoding === 'identity') {
106:       length = req.headers['content-length']
107:       stream = req
108:     } else {
109:       stream = createDecompressionStream(contentEncoding, debug)
110:       req.pipe(stream)
111:     }
112:   } catch (err) {
113:     return next(err)
114:   }
115: 
116:   // assert charset is supported
117:   if (verify && encoding !== null && !iconv.encodingExists(encoding)) {
118:     return next(createError(415, 'unsupported charset "' + encoding.toUpperCase() + '"', {
119:       charset: encoding.toLowerCase(),
120:       type: 'charset.unsupported'
121:     }))
122:   }
123: 
124:   // set raw-body options
125:   const rawBodyOptions = {
126:     length,
127:     encoding: verify ? null : encoding,
128:     limit: options.limit
129:   }
130: 
131:   // read body
132:   debug('read body')
133:   getBody(stream, rawBodyOptions, function (error, body) {
134:     if (error) {
135:       let _error
136: 
137:       if (error.type === 'encoding.unsupported') {
138:         // echo back charset
139:         _error = createError(415, 'unsupported charset "' + encoding.toUpperCase() + '"', {
140:           charset: encoding.toLowerCase(),
141:           type: 'charset.unsupported'
142:         })
143:       } else {
144:         // set status code on error
145:         _error = createError(400, error)
146:       }
147: 
148:       // unpipe from stream and destroy
149:       if (stream !== req) {
150:         req.unpipe()
151:         stream.destroy()
152:       }
153: 
154:       // read off entire request
155:       dump(req, function onfinished () {
156:         next(createError(400, _error))
157:       })
158:       return
159:     }
160: 
161:     // verify
162:     if (verify) {
163:       try {
164:         debug('verify body')
165:         verify(req, res, body, encoding)
166:       } catch (err) {
167:         next(createError(403, err, {
168:           body,
169:           type: err.type || 'entity.verify.failed'
170:         }))
171:         return
172:       }
173:     }
174: 
175:     // parse
176:     let str = body
177:     try {
178:       debug('parse body')
179:       str = typeof body !== 'string' && encoding !== null
180:         ? iconv.decode(body, encoding)
181:         : body
182:       req.body = parse(str, encoding)
183:     } catch (err) {
184:       next(createError(400, err, {
185:         body: str,
186:         type: err.type || 'entity.parse.failed'
187:       }))
188:       return
189:     }
190: 
191:     next()
192:   })
193: }
194: 
